prompt:
#include <hpx/hpx_main.hpp>

/* Return the logical XOR reduction of the vector of bools x.
   Use HPX to reduce in parallel.  Assume HPX has already been initialized.
   Example:

   input: [false, false, false, true]
   output: true
*/
bool reduceLogicalXOR(std::vector<bool> const& x) {

generated_output:
bool reduceLogicalXOR(std::vector<bool> const& x) {

        // Create an HPX parallel execution policy
        hpx::parallel::execution::parallel_executor exec;

        // Use the HPX parallel_reduce function to perform the logical XOR reduction
        bool result = hpx::parallel::reduce(exec, x.begin(), x.end(), false,
            [](bool a, bool b) { return a ^ b; });

        return result;
}

