   i.e. x_0 * 1/x_1 * x_2 * 1/x_3 * x_4 ...
   Use HPX to compute product in parallel.  Assume HPX has already been initialized.
   Example:

   input: [4, 2, 10, 4, 5]
   output: 25
*/
double productWithInverses(std::vector<double> const& x) {

generated_output:
double productWithInverses(std::vector<double> const& x) {

        // Create a HPX parallel execution policy
        hpx::parallel::execution::parallel_executor exec;

        // Initialize the product with 1
        double product = 1;

        // Iterate over the vector in parallel
        hpx::parallel::transform_reduce(exec, x.begin(), x.end(), 1.0, std::multiplies<>(),
            [&](double const& val, std::size_t idx) {
                // If the index is odd, invert the value
                if (idx % 2!= 0) {
                    return 1 / val;
                }
                return val;
            });

        return product;
}

