#include <hpx/hpx_main.hpp>

/* Return the value of the smallest odd number in the vector x.
   Use HPX to compute in parallel.  Assume HPX has already been initialized.
   Examples:

   input: [7, 9, 5, 2, 8, 16, 4, 1]
   output: 1

   input: [8, 36, 7, 2, 11]
   output: 7
*/
int smallestOdd(std::vector<int> const& x) {

generated_output:
int smallestOdd(std::vector<int> const& x) {

        // Create a vector of HPX tasks
        std::vector<hpx::future<int>> futures;

        // For each element in the vector, create a task that checks if the number is odd
        for (auto const& num : x) {
            futures.push_back(hpx::async([num]() {
                if (num % 2!= 0) {
                    return num;
                }
                return std::numeric_limits<int>::max();
            }));
        }

        // Get the smallest odd number
        int smallest = std::numeric_limits<int>::max();
        for (auto& future : futures) {
            int num = future.get();
            if (num < smallest) {
                smallest = num;
            }
        }

        // If no odd number was found, return a default value
        if (smallest == std::numeric_limits<int>::max()) {
            return -1;
        }

        return smallest;
}

