int smallestOdd(std::vector<int> const& x) {

        // Create a vector to hold the results of the HPX parallel computation.
        std::vector<int> results(x.size());

        // Use HPX to compute the smallest odd number in each sub-vector in parallel.
        hpx::parallel::transform(
            hpx::parallel::execution::par,
