                }
            }
        );

        // Find the smallest odd number in the results.
        int smallest = std::numeric_limits<int>::max();
        for (int const& val : results) {
            if (val < smallest) {
                smallest = val;
            }
        }

        // If no odd numbers were found, return a special value.
        if (smallest == std::numeric_limits<int>::max()) {
            return -1;
        } else {
            return smallest;
        }
}

