#include <hpx/hpx_main.hpp>

/* Return the value of the smallest odd number in the vector x.
   Use HPX to compute in parallel.  Assume HPX has already been initialized.
   Examples:

   input: [7, 9, 5, 2, 8, 16, 4, 1]
   output: 1

   input: [8, 36, 7, 2, 11]
   output: 7
*/
int smallestOdd(std::vector<int> const& x) {

generated_output:
int smallestOdd(std::vector<int> const& x) {

        // Create a vector of hpx::future objects.
        std::vector<hpx::future<int>> futures;

        // For each element in the vector, create a new HPX task that returns the smallest odd number in the subvector.
        for (size_t i = 0; i < x.size(); i++) {
            futures.push_back(hpx::async([&x, i]() {
                int min_odd = std::numeric_limits<int>::max();
                for (size_t j = i; j < x.size(); j++) {
                    if (x[j] % 2!= 0 && x[j] < min_odd) {
                        min_odd = x[j];
                    }
                }
                return min_odd;
            }));
        }

        // Get the results from the futures and find the smallest among them.
        int min_odd = std::numeric_limits<int>::max();
        for (auto& future : futures) {
            int result = future.get();
            if (result < min_odd) {
                min_odd = result;
            }
        }

        return min_odd;
}

