#include <hpx/hpx_main.hpp>

/* Return the value of the smallest odd number in the vector x.
   Use HPX to compute in parallel.  Assume HPX has already been initialized.
   Examples:

   input: [7, 9, 5, 2, 8, 16, 4, 1]
   output: 1

   input: [8, 36, 7, 2, 11]
   output: 7
*/
int smallestOdd(std::vector<int> const& x) {

generated_output:
int smallestOdd(std::vector<int> const& x) {

        // Create a vector to hold the results from each parallel execution
        std::vector<int> results(x.size());

        // Use HPX to parallelize the computation
        hpx::parallel::transform(hpx::parallel::execution::par, x.begin(), x.end(), results.begin(),
            [](int i) {
                if (i % 2!= 0) {
                    return i;
                } else {
                    return std::numeric_limits<int>::max();
                }
            });

        // Find the minimum value in the results
        auto min_it = std::min_element(results.begin(), results.end());

        // If no odd number was found, return a default value
        if (*min_it == std::numeric_limits<int>::max()) {
            return std::numeric_limits<int>::max();
        } else {
            return *min_it;
        }
}

