/* Return the sum of the minimum value at each index of vectors x and y for all indices.
   i.e. sum = min(x_0, y_0) + min(x_1, y_1) + min(x_2, y_2) + ...
   Use HPX to sum in parallel.  Assume HPX has already been initialized.
   Example:

   input: x=[3, 4, 0, 2, 3], y=[2, 5, 3, 1, 7]
   output: 10
*/
double sumOfMinimumElements(std::vector<double> const& x, std::vector<double> const& y) {

generated_output:
double sumOfMinimumElements(std::vector<double> const& x, std::vector<double> const& y) {

        // Check if the vectors have the same size
        if (x.size()!= y.size()) {
            throw std::invalid_argument("Vectors must have the same size");
        }

        // Create a vector to store the minimum values
        std::vector<double> min_values(x.size());

        // Use HPX to parallelize the calculation of minimum values
        hpx::parallel::transform(hpx::parallel::execution::par,
                                 x.begin(), x.end(),
                                 y.begin(),
                                 min_values.begin(),
                                 [](double a, double b) { return std::min(a, b); });

        // Use HPX to parallelize the calculation of the sum
        double sum = hpx::parallel::reduce(hpx::parallel::execution::par,
                                           min_values.begin(), min_values.end(),
                                           0.0,
                                           std::plus<double>());

        return sum;
}

